<template><section><div class="mb-6 flex items-center justify-between"><div><h1 class="text-2xl font-bold">{{t('traffic.title')}}</h1></div><button class="btn-ghost" @click="reconcile">↻ {{t('traffic.reconcile')}}</button></div><div class="card overflow-x-auto"><table class="w-full text-sm"><thead class="text-xs text-slate-500"><tr><th class="p-3 text-start">{{t('clients.email')}}</th><th class="p-3 text-start">{{t('traffic.upload')}}</th><th class="p-3 text-start">{{t('traffic.download')}}</th><th class="p-3 text-start">{{t('traffic.total')}}</th><th class="p-3 text-start">{{t('traffic.used')}}</th><th class="p-3 text-start">{{t('traffic.limit')}}</th><th class="p-3 text-start">{{t('traffic.lastSeen')}}</th></tr></thead><tbody><tr v-for="u in users" :key="u.id" class="border-t border-white/5"><td class="p-3">{{u.email||u.id}}</td><td class="p-3">{{fmt(u.upload)}}</td><td class="p-3">{{fmt(u.download)}}</td><td class="p-3 font-medium">{{fmt(Number(u.upload)+Number(u.download))}}</td><td class="p-3">{{fmt(u.traffic_used_bytes)}}</td><td class="p-3">{{u.traffic_limit_bytes?fmt(u.traffic_limit_bytes):t('common.never')}}</td><td class="p-3 text-slate-500">{{u.last_seen_at?new Date(u.last_seen_at).toLocaleString():'—'}}</td></tr></tbody></table></div></section></template>
<script setup lang="ts">import{ref}from'vue';import{useI18n}from'vue-i18n';import{api}from'../api/client';const{t}=useI18n(),users=ref<any[]>([]);const fmt=(n:number)=>{n=Number(n)||0;if(n<1024)return n+' B';const u=['KB','MB','GB','TB'];let i=-1,x=n;while(x>=1024&&i<3){x/=1024;i++}return x.toFixed(x>=10?0:1)+' '+u[i]};async function load(){users.value=(await api.get<any>('/traffic/summary')).users||[]}async function reconcile(){await api.post('/traffic/reconcile');await load()}load();</script>
